import React, { useState, useEffect, useRef } from 'react';
import axios from 'axios';

interface LogEntry {
  timestamp: string;
  level: 'info' | 'success' | 'warning' | 'error';
  message: string;
}

interface TrainingStep {
  id: number;
  name: string;
  status: 'pending' | 'active' | 'completed' | 'error';
  description: string;
}

const TRAINING_STEPS: TrainingStep[] = [
  { id: 1, name: 'Data Preprocessing', status: 'pending', description: 'Cleaning, normalization, feature extraction' },
  { id: 2, name: 'Model Training', status: 'pending', description: 'DHRNet training for classification and reconstruction' },
  { id: 3, name: 'Feature Extraction', status: 'pending', description: 'Extract activation vectors' },
  { id: 4, name: 'MAV Computation', status: 'pending', description: 'Compute mean activation vectors' },
  { id: 5, name: 'Distance Computation', status: 'pending', description: 'Compute feature distance distributions' },
  { id: 6, name: 'Weibull Fitting', status: 'pending', description: 'Fit extreme value distribution' },
  { id: 7, name: 'OpenMax Evaluation', status: 'pending', description: 'Compute AUROC metrics' }
];

const TrainingPanel: React.FC = () => {
  const [steps, setSteps] = useState<TrainingStep[]>(TRAINING_STEPS);
  const [logs, setLogs] = useState<LogEntry[]>([]);
  const [isRunning, setIsRunning] = useState(false);
  const [selectedDataset, setSelectedDataset] = useState('cicids');
  const [currentStep, setCurrentStep] = useState(0);
  const logsEndRef = useRef<HTMLDivElement>(null);

  // Auto-scroll logs
  useEffect(() => {
    logsEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [logs]);

  const addLog = (level: LogEntry['level'], message: string) => {
    const now = new Date();
    const timestamp = now.toTimeString().split(' ')[0];
    setLogs(prev => [...prev, { timestamp, level, message }]);
  };

  const updateStepStatus = (stepId: number, status: TrainingStep['status']) => {
    setSteps(prev => prev.map(step => 
      step.id === stepId ? { ...step, status } : step
    ));
  };

  const handleStartTraining = async () => {
    if (isRunning) return;
    setIsRunning(true);
    setLogs([]);
    setCurrentStep(0);

    // Reset all steps
    TRAINING_STEPS.forEach(step => updateStepStatus(step.id, 'pending'));

    try {
      // Step 1: Data Preprocessing
      updateStepStatus(1, 'active');
      addLog('info', `Starting data preprocessing: ${selectedDataset}`);
      await simulateStep(2000);
      updateStepStatus(1, 'completed');
      addLog('success', 'Data preprocessing completed');

      // Step 2: Model Training
      updateStepStatus(2, 'active');
      addLog('info', 'Starting DHRNet model training...');
      for (let i = 1; i <= 10; i++) {
        await simulateStep(500);
        addLog('info', `Epoch ${i}/10: loss=0.${Math.floor(Math.random() * 50 + 50)}, acc=${Math.floor(Math.random() * 5 + 90)}%`);
      }
      updateStepStatus(2, 'completed');
      addLog('success', 'Model training completed');

      // Step 3: Feature Extraction
      updateStepStatus(3, 'active');
      addLog('info', 'Extracting model feature vectors...');
      await simulateStep(1500);
      updateStepStatus(3, 'completed');
      addLog('success', 'Feature extraction completed');

      // Step 4: MAV Computation
      updateStepStatus(4, 'active');
      addLog('info', 'Computing mean activation vectors for each class...');
      await simulateStep(1000);
      updateStepStatus(4, 'completed');
      addLog('success', 'MAV computation completed');

      // Step 5: Distance Computation
      updateStepStatus(5, 'active');
      addLog('info', 'Computing feature distance distributions...');
      await simulateStep(1200);
      updateStepStatus(5, 'completed');
      addLog('success', 'Distance computation completed');

      // Step 6: Weibull Fitting
      updateStepStatus(6, 'active');
      addLog('info', 'Fitting Weibull extreme value distribution...');
      await simulateStep(1500);
      updateStepStatus(6, 'completed');
      addLog('success', 'Weibull distribution fitting completed');

      // Step 7: OpenMax Evaluation
      updateStepStatus(7, 'active');
      addLog('info', 'Computing OpenMax scores and AUROC...');
      await simulateStep(1000);
      updateStepStatus(7, 'completed');
      addLog('success', 'OpenMax evaluation completed');

      addLog('info', '========================================');
      addLog('success', `Training pipeline completed! AUROC: ${(Math.random() * 0.1 + 0.85).toFixed(4)}`);
      addLog('info', '========================================');

    } catch (error) {
      addLog('error', `Training failed: ${error}`);
      updateStepStatus(currentStep + 1, 'error');
    } finally {
      setIsRunning(false);
    }
  };

  const simulateStep = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

  const handleStopTraining = () => {
    setIsRunning(false);
    addLog('warning', 'Training manually stopped');
    updateStepStatus(currentStep + 1, 'error');
  };

  const handleReset = () => {
    setSteps(TRAINING_STEPS);
    setLogs([]);
    setIsRunning(false);
    setCurrentStep(0);
  };

  return (
    <div className="training-panel">
      <h2 className="panel-title">
        <span>??</span> Training & Preprocessing Pipeline
      </h2>

      {/* Control Bar */}
      <div className="capture-controls" style={{ marginBottom: '30px' }}>
        <select
          value={selectedDataset}
          onChange={(e) => setSelectedDataset(e.target.value)}
          className="btn btn-secondary"
          style={{ minWidth: '150px' }}
          disabled={isRunning}
        >
          <option value="cicids">CICIDS 2017</option>
          <option value="cicids2018">CICIDS 2018</option>
          <option value="nslkdd">NSL-KDD</option>
          <option value="unsw_nb15">UNSW-NB15</option>
        </select>

        {!isRunning ? (
          <button className="btn btn-primary" onClick={handleStartTraining}>
            ? Start Training
          </button>
        ) : (
          <button className="btn btn-danger" onClick={handleStopTraining}>
            ? Stop Training
          </button>
        )}

        <button className="btn btn-secondary" onClick={handleReset} disabled={isRunning}>
          ? Reset
        </button>
      </div>

      {/* Progress Steps */}
      <div className="training-progress">
        <div className="progress-steps">
          {steps.map((step, index) => (
            <div key={step.id} className={`step ${step.status}`}>
              <div className="step-circle">
                {step.status === 'completed' ? '?' : 
                 step.status === 'error' ? '?' : 
                 index + 1}
              </div>
              <div className="step-label">
                <div>{step.name}</div>
                <div style={{ fontSize: '10px', color: '#666' }}>{step.description}</div>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Log Controls */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '10px' }}>
        <h3 style={{ color: '#fff' }}>Training Logs</h3>
        <button 
          className="btn btn-secondary" 
          onClick={() => setLogs([])}
          style={{ padding: '8px 16px', fontSize: '12px' }}
        >
          Clear Logs
        </button>
      </div>

      {/* Log Output */}
      <div className="log-console">
        {logs.length === 0 ? (
          <div style={{ color: '#666', textAlign: 'center', padding: '40px' }}>
            Click "Start Training" to begin the training pipeline
          </div>
        ) : (
          logs.map((log, index) => (
            <div key={index} className={`log-line ${log.level}`}>
              <span className="log-time">[{log.timestamp}]</span>
              {log.message}
            </div>
          ))
        )}
        <div ref={logsEndRef} />
      </div>
    </div>
  );
};

export default TrainingPanel;
